+function compareDeterministicText(left: string, right: string): number {
+  const leftFolded = left.toLowerCase();
+  const rightFolded = right.toLowerCase();
+  if (leftFolded < rightFolded) {
+    return -1;
+  }
+  if (leftFolded > rightFolded) {
+    return 1;
+  }
+  if (left < right) {
+    return -1;
+  }
+  if (left > right) {
+    return 1;
+  }
+  return 0;
+}
